id: amphib
name: Amphib
system: rifts
source_book: Rifts World Book 7: Underseas p.98-100
category: rcc
attribute_dice:
  IQ: "3d6"
  ME: "3d6"
  MA: "4d6"
  PS: "3d6+12"
  PP: "4d6"
  PE: "4d6"
